-- Lô 47 (15/11/2026): 25 bài Viết B2 cho cây Luyện tập (B2-PE-1 đến PE-5), sinh bởi scripts/nhap/lo47_viet_b2.mjs.
-- 4 miễn phí, 21 VIP 19.000 đ; bài « essai de 250 mots » có time_limit 60.
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe01n1e03o', 'practice', 'Écriture B2 : contribution à un débat', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Lisez le sujet, répondez aux questions, puis écrivez seulement le plan. Vous ne devez pas écrire le texte complet.</p>', '<p><strong>Sujet.</strong> Votre ville envisage d''interdire les voitures dans le centre historique le week-end. Le site de la mairie ouvre un espace de débat. Vous y publiez une contribution argumentée dans laquelle vous donnez votre position, en vous appuyant sur des exemples précis. (250 mots minimum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une contribution (nom féminin) : bài đóng góp ý kiến\n• envisager de (verbe) : dự tính\n• s''appuyer sur (verbe) : dựa vào\n• une navette (nom féminin) : xe đưa đón\n• un bilan (nom masculin) : tổng kết","explications":"• Bài đóng góp tranh luận cần lập trường ngay từ mở bài, không để tới cuối mới nói mình nghĩ gì.\n• Một luận điểm nhượng bộ kèm giải pháp làm bài B2 thuyết phục hơn ba luận điểm cùng một chiều.","kyNang":"B2-PE-1","vong":"hoc","thuTu":2}'::jsonb, '2026-11-15T08:00:00.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n14000', 'b2pe01n1e03o', 1, 'qcm', 'Quel genre de texte faut-il écrire ?', '{"options":["une contribution à un débat en ligne","une lettre formelle adressée au maire","un article pour le journal de la ville"]}'::jsonb, '{"answer":0}'::jsonb, '« Vous y publiez une contribution argumentée »: bài đăng trên không gian tranh luận của trang mạng, không phải thư gửi riêng thị trưởng.'), ('qmwh84n14001', 'b2pe01n1e03o', 2, 'qcm', 'Qui va lire votre texte ?', '{"options":["les touristes qui visitent le centre historique","les habitants et la mairie qui suivent le débat","seulement le maire, qui lira le texte seul dans son bureau"]}'::jsonb, '{"answer":1}'::jsonb, '« Le site de la mairie ouvre un espace de débat »: người đọc là cư dân tham gia tranh luận và toà thị chính. Giọng lịch sự, rõ ràng, hướng tới cộng đồng.'), ('qmwh84n14002', 'b2pe01n1e03o', 3, 'qcm', 'Que doit contenir le texte ?', '{"options":["une position claire, appuyée sur des exemples précis","le récit détaillé d''une journée en voiture en ville","un résumé neutre et complet de l''avis de chacun des habitants"]}'::jsonb, '{"answer":0}'::jsonb, '« vous donnez votre position, en vous appuyant sur des exemples précis »: phải chọn phe và có ví dụ cụ thể. Bài trung lập là thiếu nhiệm vụ.'), ('qmwh84n14003', 'b2pe01n1e03o', 4, 'open', 'Écrivez le plan : introduction (avec votre position), trois arguments avec chacun un exemple, conclusion. (60 mots minimum)', '{}'::jsonb, '{"model":"Introduction : je rappelle le projet de la mairie et je dis que je suis favorable, à condition d''améliorer les transports.\nArgument 1 : un centre plus agréable. Exemple : à Pontevedra, en Espagne, les commerces du centre ont gardé leurs clients après la fermeture aux voitures.\nArgument 2 : moins de pollution et de bruit le week-end. Exemple : les familles pourraient se promener sans danger dans la rue des Halles.\nArgument 3 (concession) : les personnes âgées et les livreurs. Exemple : prévoir une navette gratuite et des horaires de livraison le matin.\nConclusion : proposer un essai de trois mois, puis un bilan public avec les habitants."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe02n1g03p', 'practice', 'Écriture B2 : une critique de film', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Lisez le sujet, répondez aux questions, puis écrivez seulement le plan de la critique.</p>', '<p><strong>Sujet.</strong> Un magazine culturel en ligne lance la rubrique « Le film qui m''a surpris ». Vous écrivez une critique d''un film que vous avez vu récemment : vous le présentez brièvement, vous donnez votre jugement argumenté et vous dites à quel public vous le recommandez. (250 mots minimum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une critique (nom féminin) : bài phê bình\n• une rubrique (nom féminin) : chuyên mục\n• le jeu des acteurs (nom masculin) : diễn xuất\n• le rythme (nom masculin) : nhịp phim\n• recommander (verbe) : giới thiệu, khuyên xem","explications":"• Bài phê bình B2 = trình bày ngắn + nhận định có lý do + lời khuyên cho đối tượng cụ thể.\n• Nên có cả điểm mạnh lẫn điểm yếu: nhận định cân bằng đọc đáng tin hơn lời khen một chiều.","isPremium":true,"price":19000,"kyNang":"B2-PE-1","vong":"hoc","thuTu":3}'::jsonb, '2026-11-15T08:00:01.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n14004', 'b2pe02n1g03p', 1, 'qcm', 'Combien de tâches le sujet vous demande-t-il ?', '{"options":["deux : résumer le film et noter les acteurs","trois : présenter, juger, recommander","une seule : raconter l''histoire du film"]}'::jsonb, '{"answer":1}'::jsonb, '« vous le présentez brièvement » … « vous donnez votre jugement argumenté » … « à quel public vous le recommandez »: ba nhiệm vụ, thiếu một là mất điểm phần “respect de la consigne”.'), ('qmwh84n14005', 'b2pe02n1g03p', 2, 'qcm', 'Comment doit être la présentation du film ?', '{"options":["courte, pour laisser de la place au jugement","complète, en racontant aussi la fin du film","longue, car c''est la partie la plus importante"]}'::jsonb, '{"answer":0}'::jsonb, '« vous le présentez brièvement »: vài câu về thể loại, đạo diễn, cốt truyện chính. Kể cả kết phim là lỗi của bài phê bình.'), ('qmwh84n14006', 'b2pe02n1g03p', 3, 'qcm', 'Comment doit être votre jugement ?', '{"options":["argumenté, avec des éléments précis du film","limité à une note sur dix, sans explication","fondé sur l''avis des journalistes les plus connus"]}'::jsonb, '{"answer":0}'::jsonb, '« votre jugement argumenté »: mỗi nhận xét (diễn xuất, âm nhạc, kịch bản) cần một cảnh hay chi tiết cụ thể làm ví dụ.'), ('qmwh84n14007', 'b2pe02n1g03p', 4, 'open', 'Écrivez le plan de votre critique : titre, présentation, deux ou trois points du jugement avec un exemple, recommandation. (60 mots minimum)', '{}'::jsonb, '{"model":"Titre : « Les Ponts de Lyon », une comédie qui cache un vrai drame.\nPrésentation : film français de 2026, deux frères qui ne se parlent plus doivent vider la maison de leur mère.\nJugement 1 : des acteurs justes. Exemple : la scène du grenier, où les frères rient puis pleurent sans un mot.\nJugement 2 : un rythme trop lent au milieu. Exemple : vingt minutes de disputes répétitives.\nJugement 3 : une musique discrète et réussie.\nRecommandation : pour les adultes et les grands adolescents, pas pour ceux qui attendent une comédie légère."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe03n1g03q', 'practice', 'Écriture B2 : un rapport pour le conseil', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Lisez le sujet, répondez aux questions, puis écrivez seulement le plan du rapport.</p>', '<p><strong>Sujet.</strong> Vous êtes délégué des étudiants de votre résidence universitaire. Le conseil d''administration vous demande un rapport sur les problèmes de la résidence (bruit, salle de travail, laverie) et sur les solutions possibles. Vous rédigez ce rapport. (250 mots minimum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un délégué (nom masculin) : đại diện\n• le conseil d''administration (nom masculin) : hội đồng quản trị\n• un constat (nom masculin) : sự ghi nhận hiện trạng\n• une laverie (nom féminin) : phòng giặt\n• une réunion de suivi (nom féminin) : cuộc họp theo dõi","explications":"• Báo cáo có thể dùng tiêu đề nhỏ (Objet, Constat, Propositions): người chấm đánh giá cao bố cục rõ.\n• Một con số cụ thể (12 chỗ cho 180 sinh viên) thuyết phục hơn mọi tính từ.","isPremium":true,"price":19000,"kyNang":"B2-PE-1","vong":"hoc","thuTu":4}'::jsonb, '2026-11-15T08:00:02.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n14008', 'b2pe03n1g03q', 1, 'qcm', 'Quel ton faut-il adopter ?', '{"options":["familier, comme dans un message à des amis","neutre et objectif, appuyé sur des faits","personnel et émotionnel, comme un journal intime"]}'::jsonb, '{"answer":1}'::jsonb, '« Le conseil d''administration vous demande un rapport »: báo cáo gửi hội đồng là văn bản khách quan, dựa trên sự việc và số liệu, không trút cảm xúc.'), ('qmwh84n14009', 'b2pe03n1g03q', 2, 'qcm', 'Comment organiser le rapport ?', '{"options":["le récit chronologique de votre année à la résidence","une liste de plaintes, sans aucune proposition","le constat des problèmes, puis des propositions"]}'::jsonb, '{"answer":2}'::jsonb, 'Đề hỏi hai thứ: « sur les problèmes de la résidence » và « sur les solutions possibles ». Khuôn báo cáo: hiện trạng, rồi đề xuất.'), ('qmwh84n1400a', 'b2pe03n1g03q', 3, 'qcm', 'Dans ce rapport, qui êtes-vous ?', '{"options":["un étudiant qui se plaint de sa chambre, pour lui seul","le délégué qui parle au nom des étudiants","le directeur qui gère la résidence"]}'::jsonb, '{"answer":1}'::jsonb, '« Vous êtes délégué des étudiants »: dùng “nous”, “les résidents”, dẫn ý kiến chung chứ không chỉ chuyện của riêng mình.'), ('qmwh84n1400b', 'b2pe03n1g03q', 4, 'open', 'Écrivez le plan du rapport : objet, introduction, constat (trois problèmes), propositions, conclusion. (60 mots minimum)', '{}'::jsonb, '{"model":"Objet : rapport sur les conditions de vie à la résidence Les Tilleuls.\nIntroduction : demande du conseil, méthode (questionnaire rempli par 64 résidents).\nConstat : 1. le bruit le soir dans le bâtiment B ; 2. une salle de travail trop petite (12 places pour 180 étudiants) ; 3. deux machines de la laverie sur quatre en panne depuis octobre.\nPropositions : des horaires de calme après 22 heures, ouvrir une deuxième salle au rez-de-chaussée, réparer les machines et afficher un numéro pour signaler les pannes.\nConclusion : priorité à la laverie, réunion de suivi en janvier."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe04n1g03r', 'practice', 'Écriture B2 : quel genre pour ce sujet ?', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Lisez les six sujets. Pour chacun, choisissez le genre du texte et le rôle que vous jouez.</p>', '<p><strong>Sujet A.</strong> Le directeur de votre lycée veut supprimer les voyages scolaires pour faire des économies. Au nom des élèves, vous lui écrivez pour le faire changer d''avis.</p><p><strong>Sujet B.</strong> Le journal de votre ville publie un dossier sur le télétravail. On vous demande un article qui présente les avantages et les limites de ce mode de travail, avec votre opinion.</p><p><strong>Sujet C.</strong> Vous avez acheté un abonnement dans une salle de sport, mais la salle est fermée depuis un mois. Vous écrivez au service client pour obtenir un remboursement.</p><p><strong>Sujet D.</strong> Sur le forum d''un site d''actualité, la question du jour est : « Faut-il interdire les téléphones au collège ? » Vous participez au débat.</p><p><strong>Sujet E.</strong> Vous avez vu une pièce de théâtre très attendue. Le blog culturel de votre université vous demande votre avis argumenté sur ce spectacle.</p><p><strong>Sujet F.</strong> Votre association a organisé un festival de quartier. La mairie, qui l''a financé, vous demande de faire le bilan de l''événement et de proposer des améliorations.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• au nom de (expression) : thay mặt\n• un dossier (nom masculin) : chuyên đề (báo)\n• un abonnement (nom masculin) : gói đăng ký, thẻ hội viên\n• un internaute (nom masculin) : người dùng mạng\n• financer (verbe) : tài trợ","explications":"• Tìm động từ và người nhận trong đề: « vous lui écrivez » là thư, « on vous demande un article » là bài báo, « faire le bilan » là báo cáo.\n• Vai của mình quyết định đại từ: đại diện thì « nous », khách hàng thì « je ».","isPremium":true,"price":19000,"kyNang":"B2-PE-1","vong":"on","thuTu":5}'::jsonb, '2026-11-15T08:00:03.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1400c', 'b2pe04n1g03r', 1, 'qcm', 'Sujet A : genre et rôle ?', '{"options":["une lettre formelle, comme représentant des élèves","un article du journal du lycée, comme journaliste","un message sur un forum, comme élève qui reste anonyme"]}'::jsonb, '{"answer":0}'::jsonb, '« Au nom des élèves, vous lui écrivez »: thư trang trọng gửi hiệu trưởng, mình là đại diện học sinh.'), ('qmwh84n1400d', 'b2pe04n1g03r', 2, 'qcm', 'Sujet B : genre et rôle ?', '{"options":["une lettre de réclamation adressée à la rédaction du journal","un article argumenté, pour les lecteurs du journal","une critique d''un livre consacré au télétravail"]}'::jsonb, '{"answer":1}'::jsonb, '« On vous demande un article »: bài báo nghị luận, nêu lợi, hạn chế rồi ý kiến.'), ('qmwh84n1400e', 'b2pe04n1g03r', 3, 'qcm', 'Sujet C : genre et rôle ?', '{"options":["une lettre de réclamation, comme client","un rapport, comme employé de la salle","une contribution à un débat, comme sportif"]}'::jsonb, '{"answer":0}'::jsonb, '« pour obtenir un remboursement »: khiếu nại của khách hàng, có sự việc và yêu cầu cụ thể.'), ('qmwh84n1400f', 'b2pe04n1g03r', 4, 'qcm', 'Sujet D : genre et rôle ?', '{"options":["un rapport officiel, comme principal du collège","une lettre au ministre, comme parent d''élève","une contribution à un débat, comme internaute"]}'::jsonb, '{"answer":2}'::jsonb, '« Vous participez au débat »: bài đóng góp trên diễn đàn, có lập trường và lập luận.'), ('qmwh84n1400g', 'b2pe04n1g03r', 5, 'qcm', 'Sujet E : genre et rôle ?', '{"options":["une lettre formelle, comme directeur du théâtre","une critique, comme spectateur","un rapport, comme organisateur du spectacle"]}'::jsonb, '{"answer":1}'::jsonb, '« votre avis argumenté sur ce spectacle »: bài phê bình của người đã xem.'), ('qmwh84n1400h', 'b2pe04n1g03r', 6, 'qcm', 'Sujet F : genre et rôle ?', '{"options":["un message de forum, comme habitant mécontent","une critique du festival, comme simple visiteur","un rapport, comme membre de l''association"]}'::jsonb, '{"answer":2}'::jsonb, '« faire le bilan de l''événement et de proposer des améliorations »: báo cáo tổng kết gửi bên tài trợ.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe05n1g03s', 'practice', 'Écriture B2 : analysez le sujet', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Lisez le sujet. Répondez aux deux questions, puis écrivez votre analyse complète et votre plan.</p>', '<p><strong>Sujet.</strong> Votre entreprise envisage de remplacer les bureaux individuels par un grand espace ouvert (open space). Le directeur des ressources humaines invite les salariés à lui écrire. Vous lui adressez une lettre dans laquelle vous exposez les conséquences possibles de ce projet et vous faites des propositions. (250 mots minimum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un espace ouvert (nom masculin) : văn phòng mở\n• les ressources humaines (nom féminin pluriel) : nhân sự\n• exposer (verbe) : trình bày\n• une cloison (nom féminin) : vách ngăn\n• constructif (adjectif) : mang tính xây dựng","explications":"• Phân tích đề đủ bốn câu hỏi: tôi là ai, viết cho ai, để làm gì, giọng nào.\n• Đề có hai nhiệm vụ (exposer, faire des propositions): dàn ý phải có phần riêng cho từng nhiệm vụ.","isPremium":true,"price":19000,"kyNang":"B2-PE-1","vong":"chot","thuTu":6}'::jsonb, '2026-11-15T08:00:04.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1400i', 'b2pe05n1g03s', 1, 'qcm', 'Quel genre de texte faut-il écrire ?', '{"options":["une lettre formelle","un article d''opinion","un rapport d''activité"]}'::jsonb, '{"answer":0}'::jsonb, '« Vous lui adressez une lettre »: thư trang trọng, có công thức mở và kết.'), ('qmwh84n1400j', 'b2pe05n1g03s', 2, 'qcm', 'Qui est le destinataire ?', '{"options":["l''ensemble de vos collègues de bureau","le président de l''entreprise et son équipe","le directeur des ressources humaines"]}'::jsonb, '{"answer":2}'::jsonb, '« Le directeur des ressources humaines invite les salariés à lui écrire »: viết cho giám đốc nhân sự, xưng “Monsieur le Directeur” hoặc “Madame la Directrice”.'), ('qmwh84n1400k', 'b2pe05n1g03s', 3, 'open', 'Écrivez votre analyse (rôle, destinataire, but, ton) puis un plan détaillé. (80 mots minimum)', '{}'::jsonb, '{"model":"Rôle : salarié du service comptable, depuis six ans dans l''entreprise.\nDestinataire : le directeur des ressources humaines. Ton : formel, constructif, sans agressivité.\nBut : exposer les conséquences du projet et faire des propositions (deux tâches).\nPlan :\n1. Formule d''appel, objet de la lettre, je réponds à l''invitation de la direction.\n2. Conséquences positives : plus d''échanges entre services, par exemple entre la comptabilité et les ventes.\n3. Conséquences négatives : le bruit et le manque de concentration ; exemple des appels téléphoniques des commerciaux.\n4. Propositions : des salles fermées pour les appels, des cloisons basses, un essai de trois mois avec un questionnaire.\n5. Conclusion : disponibilité pour participer à un groupe de travail, formule de politesse."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe06n1g03t', 'practice', 'Écriture B2 : dites-le autrement', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Chaque phrase est familière. Complétez la version soutenue, ou choisissez la meilleure formulation.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• familier (adjectif) : khẩu ngữ, suồng sã\n• soutenu (adjectif) : trang trọng\n• signaler (verbe) : báo, phản ánh\n• résider dans (verbe) : nằm ở\n• négliger (verbe) : xem nhẹ","explications":"• Ba dấu hiệu khẩu ngữ hay sót: bỏ « ne », dùng « ça », dùng « on » thay « nous ».\n• Thay động từ chung (avoir, faire, dire) bằng động từ chính xác là cách nâng giọng nhanh nhất.","kyNang":"B2-PE-2","vong":"hoc","thuTu":2}'::jsonb, '2026-11-15T08:00:05.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1400l', 'b2pe06n1g03t', 1, 'fill', '« Je bosse dans une banque. » → « Je ______ dans une banque. »', '{}'::jsonb, '{"accepted":"travaille"}'::jsonb, '« Je bosse » là khẩu ngữ. Văn viết trang trọng: travailler.'), ('qmwh84n1400m', 'b2pe06n1g03t', 2, 'fill', '« J''ai pas le temps. » → « Je ______ pas le temps. »', '{}'::jsonb, '{"accepted":"n''ai|n’ai"}'::jsonb, '« J''ai pas le temps » bỏ mất “ne”: văn viết luôn giữ đủ hai vế phủ định.'), ('qmwh84n1400n', 'b2pe06n1g03t', 3, 'fill', '« C''est super cher. » → « C''est extrêmement ______. »', '{}'::jsonb, '{"accepted":"cher|coûteux|onéreux"}'::jsonb, '« super » là khẩu ngữ, thay bằng « extrêmement »; tính từ có thể giữ « cher » hoặc nâng lên coûteux, onéreux.'), ('qmwh84n1400o', 'b2pe06n1g03t', 4, 'fill', '« Il y a plein de problèmes. » → « Il y a ______ problèmes. » (deux mots)', '{}'::jsonb, '{"accepted":"beaucoup de|bien des|nombre de"}'::jsonb, '« plein de » là khẩu ngữ. Trang trọng: beaucoup de, bien des, nombre de.'), ('qmwh84n1400p', 'b2pe06n1g03t', 5, 'fill', '« Ça m''énerve. » → « Cela m''______. »', '{}'::jsonb, '{"accepted":"agace|irrite|exaspère"}'::jsonb, '« Ça » thành « cela », “énerver” thành agacer, irriter, exaspérer.'), ('qmwh84n1400q', 'b2pe06n1g03t', 6, 'fill', '« Les gens pensent que… » → « La ______ des citoyens pense que… »', '{}'::jsonb, '{"accepted":"plupart|majorité"}'::jsonb, '« Les gens » quá chung. Bài nghị luận B2: la plupart des citoyens, la majorité des citoyens.'), ('qmwh84n1400r', 'b2pe06n1g03t', 7, 'qcm', 'Quelle phrase convient dans une lettre au maire ?', '{"options":["Je me permets de vous signaler un problème.","Je vous écris vite fait pour un petit problème.","Y a un souci dans ma rue que je veux vous dire."]}'::jsonb, '{"answer":0}'::jsonb, '« Je me permets de vous signaler »: công thức lịch sự để mở đầu một lời phản ánh.'), ('qmwh84n1400s', 'b2pe06n1g03t', 8, 'qcm', '« Le truc, c''est que les bus sont toujours en retard. » Version soutenue :', '{"options":["Bon, les bus, ils sont toujours en retard, voilà, c''est tout.","Le problème réside dans le retard constant des bus.","Le truc, c''est vraiment que les bus sont en retard."]}'::jsonb, '{"answer":1}'::jsonb, '« réside dans » + danh từ hoá (le retard constant) là cách viết B2. « Le truc » và câu tách chủ ngữ « les bus, ils » là khẩu ngữ.'), ('qmwh84n1400t', 'b2pe06n1g03t', 9, 'qcm', '« On s''en fiche de l''environnement. » Version soutenue :', '{"options":["On se moque pas mal de l''environnement, hein.","Tout le monde s''en fiche, de l''environnement.","L''environnement est souvent négligé."]}'::jsonb, '{"answer":2}'::jsonb, '« négligé » thay cho « s''en fiche ». Câu bị động còn tránh được « on » mơ hồ.'), ('qmwh84n1400u', 'b2pe06n1g03t', 10, 'qcm', 'Quel mot est familier ?', '{"options":["ouvrage","livre","bouquin"]}'::jsonb, '{"answer":2}'::jsonb, '« bouquin » là khẩu ngữ của livre; « ouvrage » là từ trang trọng.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe07n1g03u', 'practice', 'Écriture B2 : veuillez agréer', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Complétez les formules de la lettre formelle, puis choisissez la bonne réponse.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une formule d''appel (nom féminin) : câu xưng hô mở thư\n• une formule de politesse (nom féminin) : câu chào kết thư\n• agréer (verbe) : đón nhận (thư trang trọng)\n• la considération (nom féminin) : sự kính trọng\n• un renseignement (nom masculin) : thông tin","explications":"• Câu kết phải lặp lại đúng câu xưng hô: mở « Monsieur le Maire, » thì kết « …, Monsieur le Maire, l''expression… ».\n• Thuộc lòng một câu mở và một câu kết là đủ cho mọi thư DELF B2.","isPremium":true,"price":19000,"kyNang":"B2-PE-2","vong":"hoc","thuTu":3}'::jsonb, '2026-11-15T08:00:06.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1400v', 'b2pe07n1g03u', 1, 'fill', 'Formule d''appel quand on ne connaît pas le destinataire : « ______, Monsieur, »', '{}'::jsonb, '{"accepted":"Madame"}'::jsonb, 'Không biết người nhận là ai: “Madame, Monsieur,”. Không dùng “Cher” với người lạ.'), ('qmwh84n1400w', 'b2pe07n1g03u', 2, 'fill', '« Je vous ______ d''agréer, Madame, Monsieur, l''expression de mes salutations distinguées. »', '{}'::jsonb, '{"accepted":"prie"}'::jsonb, 'Công thức kết chuẩn: “Je vous prie d''agréer…”.'), ('qmwh84n1400x', 'b2pe07n1g03u', 3, 'fill', '« Veuillez ______, Monsieur le Maire, l''expression de ma haute considération. »', '{}'::jsonb, '{"accepted":"agréer|recevoir"}'::jsonb, '“Veuillez agréer” hoặc “Veuillez recevoir”: mệnh lệnh lịch sự của vouloir.'), ('qmwh84n1400y', 'b2pe07n1g03u', 4, 'fill', '« Dans l''______ de votre réponse, je vous prie d''agréer… »', '{}'::jsonb, '{"accepted":"attente"}'::jsonb, '“Dans l''attente de votre réponse”: câu nối quen thuộc trước lời chào cuối.'), ('qmwh84n1400z', 'b2pe07n1g03u', 5, 'fill', '« Je me ______ à votre disposition pour tout renseignement complémentaire. »', '{}'::jsonb, '{"accepted":"tiens"}'::jsonb, '“Je me tiens à votre disposition”: sẵn sàng cung cấp thêm thông tin.'), ('qmwh84n14010', 'b2pe07n1g03u', 6, 'qcm', 'Pour écrire au maire, la formule d''appel correcte est :', '{"options":["Cher Maire,","Salut Monsieur le Maire,","Monsieur le Maire,"]}'::jsonb, '{"answer":2}'::jsonb, '« Monsieur le Maire » (hoặc “Madame la Maire”): gọi theo chức vụ, không dùng “Cher” hay « Salut ».'), ('qmwh84n14011', 'b2pe07n1g03u', 7, 'qcm', 'Quelle phrase ouvre bien une lettre de réclamation ?', '{"options":["Je vous écris parce que franchement j''en ai assez de votre service client.","Je vous écris au sujet de la commande n° 2231, livrée le 4 mai.","Coucou, petit souci avec ma commande n° 2231 livrée le 4 mai."]}'::jsonb, '{"answer":1}'::jsonb, '« au sujet de » + thông tin chính xác (số đơn, ngày): mở thư khiếu nại rõ ràng, không cảm xúc.'), ('qmwh84n14012', 'b2pe07n1g03u', 8, 'qcm', 'Quelle formule finale est trop familière pour une lettre formelle ?', '{"options":["Veuillez recevoir mes sincères salutations.","Je vous prie d''agréer mes salutations distinguées.","Bisous et à bientôt !"]}'::jsonb, '{"answer":2}'::jsonb, '« Bisous et à bientôt ! » chỉ dùng với bạn bè, người thân.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe08n1h03v', 'practice', 'Écriture B2 : formuler une demande', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Choisissez la formulation la plus adaptée, puis réécrivez les deux demandes.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un délai (nom masculin) : thời hạn\n• atténuer (verbe) : làm nhẹ bớt\n• reporter (verbe) : hoãn\n• savoir gré (expression) : biết ơn\n• verser (verbe) : chuyển (tiền)","explications":"• Ba công cụ làm mềm lời yêu cầu: conditionnel (pourriez-vous), câu hỏi đảo (serait-il possible), lời cảm ơn trước.\n• Kèm lý do ngắn sau yêu cầu (« En effet, … ») để lời đề nghị có cơ sở.","isPremium":true,"price":19000,"kyNang":"B2-PE-2","vong":"hoc","thuTu":4}'::jsonb, '2026-11-15T08:00:07.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n14013', 'b2pe08n1h03v', 1, 'qcm', 'Demande la plus polie à un professeur :', '{"options":["Pourriez-vous m''accorder un délai supplémentaire ?","Vous pouvez me donner plus de temps pour le devoir ?","Donnez-moi encore une semaine, s''il vous plaît."]}'::jsonb, '{"answer":0}'::jsonb, '« Pourriez-vous »: conditionnel làm lời đề nghị mềm hơn; « accorder un délai » là từ chính xác.'), ('qmwh84n14014', 'b2pe08n1h03v', 2, 'qcm', '« Je veux un rendez-vous. » Version polie :', '{"options":["Il me faut un rendez-vous, et rapidement.","Je souhaiterais obtenir un rendez-vous.","Je veux vraiment un rendez-vous, merci bien."]}'::jsonb, '{"answer":1}'::jsonb, '« Je souhaiterais » (conditionnel) thay cho « je veux », vốn nghe như ra lệnh.'), ('qmwh84n14015', 'b2pe08n1h03v', 3, 'qcm', 'Quelle formule remercie à l''avance de façon soutenue ?', '{"options":["Je vous serais reconnaissant de bien vouloir me répondre.","Merci de me répondre très vite, parce que c''est vraiment très urgent.","Répondez-moi vite, je vous remercie."]}'::jsonb, '{"answer":0}'::jsonb, '« Je vous serais reconnaissant de bien vouloir »: công thức trang trọng nhất cho một yêu cầu.'), ('qmwh84n14016', 'b2pe08n1h03v', 4, 'qcm', 'Pour atténuer une demande, on peut écrire :', '{"options":["Il faut absolument reporter la réunion de lundi.","Reportez la réunion à jeudi, c''est mieux.","Serait-il possible de reporter la réunion ?"]}'::jsonb, '{"answer":2}'::jsonb, '« Serait-il possible »: câu hỏi đảo + conditionnel, để người nhận có quyền quyết định.'), ('qmwh84n14017', 'b2pe08n1h03v', 5, 'qcm', '« Envoyez-moi le document. » Version adaptée à un supérieur :', '{"options":["Tu peux m''envoyer le document quand tu as le temps ?","Envoyez-moi vite le document, merci d''avance.","Auriez-vous l''amabilité de m''envoyer le document ?"]}'::jsonb, '{"answer":2}'::jsonb, '« Auriez-vous l''amabilité de »: rất lịch sự, hợp với cấp trên. « Tu » sai quan hệ.'), ('qmwh84n14018', 'b2pe08n1h03v', 6, 'qcm', 'Quelle phrase est maladroite dans une demande officielle ?', '{"options":["J''exige une réponse avant demain, sinon je porte plainte.","Je vous remercie par avance de l''attention que vous porterez à ma demande.","Je vous saurais gré de bien vouloir me répondre dans les meilleurs délais."]}'::jsonb, '{"answer":0}'::jsonb, '« J''exige » và lời đe doạ « sinon je porte plainte » quá gay gắt cho thư đầu tiên. Có thể nhắc tới bước tiếp theo, nhưng bằng giọng bình tĩnh.'), ('qmwh84n14019', 'b2pe08n1h03v', 7, 'open', 'Réécrivez poliment cette demande à la direction d''un hôtel : « Changez ma chambre, elle est trop bruyante. » (15 mots minimum)', '{}'::jsonb, '{"model":"Serait-il possible de changer de chambre ? En effet, la mienne donne sur la rue et elle est très bruyante la nuit."}'::jsonb, null), ('qmwh84n1401a', 'b2pe08n1h03v', 8, 'open', 'Réécrivez poliment cette demande au service des bourses : « Je veux savoir pourquoi ma bourse n''est pas arrivée. » (15 mots minimum)', '{}'::jsonb, '{"model":"Je vous serais reconnaissant de bien vouloir m''indiquer pourquoi ma bourse ne m''a pas encore été versée ce mois-ci."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe09n1h03w', 'practice', 'Écriture B2 : corrigez le registre', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Ce courriel est adressé au directeur d''une médiathèque, mais le registre est souvent familier. Réécrivez-le entièrement dans un registre soutenu, sans changer les idées. (100 mots minimum)</p>', '<p>Monsieur le Directeur,</p><p>Je vous écris parce que franchement, les nouveaux horaires de la médiathèque, c''est n''importe quoi. Maintenant vous fermez à 17 heures, du coup les gens qui bossent peuvent plus venir. Moi, par exemple, je sors du boulot à 18 heures, donc je suis coincé. En plus, le samedi, y a un monde fou et on trouve pas de place pour bosser.</p><p>Ce serait cool que vous ouvriez plus tard au moins deux soirs par semaine.</p><p>Je vous prie d''agréer, Monsieur le Directeur, mes salutations distinguées.</p><p>Sophie Garnier</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un usager (nom masculin) : người sử dụng (dịch vụ công)\n• la fréquentation (nom féminin) : lượng người tới\n• se rendre (verbe) : đi tới\n• prolonger (verbe) : kéo dài\n• par ailleurs (locution) : ngoài ra","explications":"• Đánh dấu mọi chữ khẩu ngữ trước khi viết lại: franchement, c''est n''importe quoi, du coup, bosser, boulot, y a, cool.\n• Đổi lời phàn nàn chung (« c''est n''importe quoi ») thành nhận định có lý do (« peu adaptés aux besoins des usagers »).","isPremium":true,"price":19000,"kyNang":"B2-PE-2","vong":"on","thuTu":5}'::jsonb, '2026-11-15T08:00:08.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1401b', 'b2pe09n1h03w', 1, 'open', 'Écrivez la version soutenue du courriel.', '{}'::jsonb, '{"model":"Monsieur le Directeur,\n\nJe me permets de vous écrire au sujet des nouveaux horaires de la médiathèque, qui me semblent peu adaptés aux besoins des usagers. Depuis que l''établissement ferme à 17 heures, les personnes qui travaillent ne peuvent plus s''y rendre en semaine. Je suis moi-même dans cette situation, puisque je quitte mon travail à 18 heures. Par ailleurs, le samedi, la fréquentation est telle qu''il devient difficile de trouver une place pour étudier.\n\nC''est pourquoi je souhaiterais savoir s''il serait possible de prolonger l''ouverture au moins deux soirs par semaine.\n\nDans l''attente de votre réponse, je vous prie d''agréer, Monsieur le Directeur, l''expression de mes salutations distinguées.\n\nSophie Garnier"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe10n1h03x', 'practice', 'Écriture B2 : de familier à soutenu', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Lucas a écrit ce message à un ami. Vous êtes Lucas : écrivez à l''agence Immo Centre une lettre formelle de réclamation. Exposez les faits, demandez une intervention rapide et indiquez ce que vous ferez si vous ne recevez pas de réponse. (200 mots minimum)</p>', '<p>Salut Tom !</p><p>Galère totale avec mon appart… Le chauffage marche plus depuis trois semaines, je me caille. J''ai appelé l''agence quatre fois, ils m''ont dit qu''ils allaient envoyer quelqu''un, et rien. En plus, j''ai trouvé de la moisissure dans la salle de bains. Je paie 750 balles par mois pour ça !</p><p>Si ça bouge pas, je vais aller voir une asso de locataires, ou je sais pas quoi. Bref, j''en ai ras le bol.</p><p>Lucas</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un locataire (nom masculin) : người thuê nhà\n• la moisissure (nom féminin) : nấm mốc\n• s''acquitter de (verbe) : trả, thanh toán\n• décent (adjectif) : đạt chuẩn tối thiểu\n• faire valoir ses droits (expression) : đòi quyền lợi của mình","explications":"• Thư khiếu nại B2: sự việc có ngày tháng, việc đã làm, yêu cầu rõ, hạn chót, bước tiếp theo nếu không được giải quyết.\n• Lời « đe doạ » trong thư trang trọng phải bình tĩnh và hợp pháp: « je me verrai contraint de… ».","isPremium":true,"price":19000,"kyNang":"B2-PE-2","vong":"chot","thuTu":6}'::jsonb, '2026-11-15T08:00:09.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1401c', 'b2pe10n1h03x', 1, 'open', 'Écrivez la lettre formelle.', '{}'::jsonb, '{"model":"Lucas Ferrand\n14, rue des Lilas, appartement 3B\n37000 Tours\n\nAgence Immo Centre\nService de gestion locative\n\nTours, le 15 novembre 2026\n\nObjet : panne de chauffage et présence de moisissure\n\nMadame, Monsieur,\n\nLocataire de l''appartement 3B situé au 14, rue des Lilas, je me permets de vous écrire au sujet de deux problèmes qui rendent ce logement difficilement habitable.\n\nEn premier lieu, le chauffage ne fonctionne plus depuis trois semaines, alors que les températures sont désormais très basses. J''ai contacté votre agence à quatre reprises par téléphone et l''on m''a assuré qu''un technicien interviendrait rapidement. Or, aucune intervention n''a eu lieu à ce jour. En second lieu, j''ai constaté la présence de moisissure sur les murs de la salle de bains, ce qui pourrait avoir des conséquences sur ma santé.\n\nJe vous rappelle que je m''acquitte chaque mois d''un loyer de 750 euros et que le propriétaire est tenu de fournir un logement décent. Je vous demande donc de bien vouloir faire réparer le chauffage et traiter la moisissure dans les plus brefs délais.\n\nSans réponse de votre part sous quinze jours, je me verrai contraint de solliciter l''aide d''une association de défense des locataires afin de faire valoir mes droits.\n\nDans l''attente de votre intervention, je vous prie d''agréer, Madame, Monsieur, l''expression de mes salutations distinguées.\n\nLucas Ferrand"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe11n1h03y', 'practice', 'Écriture B2 : taxer la viande ?', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Écrivez un paragraphe argumenté : une idée principale, une explication, puis un exemple précis. (120 mots minimum)</p>', '<p><strong>Sujet.</strong> Pour lutter contre le réchauffement climatique, certains proposent de taxer la viande, comme on taxe déjà le tabac. Êtes-vous pour ou contre ? Rédigez un paragraphe qui défend votre position avec un seul argument bien développé.</p><p><strong>Boîte à outils :</strong> en effet • c''est pourquoi • prenons l''exemple de • c''est notamment le cas de • cela montre que</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• taxer (verbe) : đánh thuế\n• le réchauffement climatique (nom masculin) : sự nóng lên toàn cầu\n• modeste (adjectif) : thu nhập thấp\n• un ménage aisé (nom masculin) : hộ khá giả\n• peser lourd (expression) : đè nặng","explications":"• Đoạn lập luận B2 = luận điểm (một câu) + giải thích (en effet) + ví dụ cụ thể + câu rút ra (cela montre que).\n• Ví dụ tốt có người, con số, tình huống: « une famille de quatre personnes » rõ hơn « les pauvres ».","kyNang":"B2-PE-3","vong":"hoc","thuTu":2}'::jsonb, '2026-11-15T08:00:10.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1501d', 'b2pe11n1h03y', 1, 'open', 'Écrivez votre paragraphe.', '{}'::jsonb, '{"model":"Selon moi, une taxe sur la viande serait injuste, car elle toucherait d''abord les familles modestes. En effet, une taxe augmente le prix de la même somme pour tout le monde, mais elle pèse beaucoup plus lourd dans le budget de ceux qui gagnent peu. Prenons l''exemple d''une famille de quatre personnes qui vit avec un seul salaire : si le poulet passe de huit à dix euros le kilo, elle ne mangera pas moins de viande par conviction écologique, mais par obligation, tandis qu''un ménage aisé ne changera rien à ses habitudes. Cela montre qu''une mesure de ce type risque de transformer un objectif collectif en effort réservé aux plus pauvres. C''est pourquoi il me semble préférable d''agir autrement, par exemple en proposant davantage de repas végétariens de qualité dans les cantines."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe12n1h03z', 'practice', 'Écriture B2 : la reconnaissance faciale', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Écrivez un paragraphe qui présente un argument, puis répond à une objection. (120 mots minimum)</p>', '<p><strong>Sujet.</strong> Votre ville veut installer des caméras de reconnaissance faciale dans les gares pour améliorer la sécurité. Dans un paragraphe, donnez un argument pour ou contre ce projet, puis répondez à l''objection principale du camp opposé.</p><p><strong>Boîte à outils :</strong> certains affirment que • on pourrait objecter que • or • cet argument ne tient pas, car • il n''en reste pas moins que</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la reconnaissance faciale (nom féminin) : nhận diện khuôn mặt\n• une objection (nom féminin) : ý phản bác\n• un suspect (nom masculin) : nghi phạm\n• à d''autres fins (expression) : cho mục đích khác\n• un quai (nom masculin) : sân ga","explications":"• Nêu ý phản bác của phe kia (« certains affirment que ») rồi đáp lại (« or, cet argument ne tient pas »): người chấm thấy bạn hiểu cả hai phía.\n• Đáp lại bằng lý do, không chỉ bằng « c''est faux ».","kyNang":"B2-PE-3","vong":"hoc","thuTu":3}'::jsonb, '2026-11-15T08:00:11.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1501e', 'b2pe12n1h03z', 1, 'open', 'Écrivez votre paragraphe.', '{}'::jsonb, '{"model":"Je suis opposée à ce projet, car il menace une liberté essentielle : celle de circuler sans être identifié. Avec ces caméras, chaque voyageur deviendrait un suspect dont le visage serait analysé, enregistré et peut-être conservé pendant des mois. Certains affirment que seules les personnes recherchées ont quelque chose à craindre. Or, cet argument ne tient pas, car les logiciels se trompent : plusieurs expériences menées à l''étranger ont montré que des innocents avaient été arrêtés à cause d''une erreur d''identification. De plus, rien ne garantit qu''un futur gouvernement n''utilisera pas ces images à d''autres fins. On pourrait objecter que la sécurité dans les gares est une vraie priorité. Il n''en reste pas moins que d''autres moyens existent, comme davantage d''agents sur les quais, qui protègent sans surveiller tout le monde."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe13n1h040', 'practice', 'Écriture B2 : le droit de vote à 16 ans', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Écrivez un paragraphe qui accepte d''abord une partie de l''argument adverse (concession), puis le réfute. (120 mots minimum)</p>', '<p><strong>Sujet.</strong> Un député propose d''abaisser l''âge du droit de vote à 16 ans. Dans un paragraphe, vous reconnaissez un point valable du camp opposé, puis vous expliquez pourquoi votre position reste la meilleure.</p><p><strong>Boîte à outils :</strong> certes • il est vrai que • j''admets que • mais • toutefois • pour autant • malgré cela</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• abaisser (verbe) : hạ xuống\n• un électeur (nom masculin) : cử tri\n• un apprenti (nom masculin) : người học nghề\n• l''orientation (nom féminin) : định hướng (học, nghề)\n• une réserve (nom féminin) : sự dè dặt","explications":"• Khuôn nhượng bộ: « Certes / Il est vrai que » + ý của phe kia, rồi « mais / toutefois » + lập trường của mình.\n• Phần sau « toutefois » phải dài hơn phần nhượng bộ: trọng tâm đoạn văn là ý của bạn.","isPremium":true,"price":19000,"kyNang":"B2-PE-3","vong":"hoc","thuTu":4}'::jsonb, '2026-11-15T08:00:12.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1501f', 'b2pe13n1h040', 1, 'open', 'Écrivez votre paragraphe.', '{}'::jsonb, '{"model":"Certes, beaucoup de jeunes de seize ans s''intéressent peu à la politique, et il est vrai que certains voteraient sans bien connaître les programmes. Toutefois, cet argument pourrait s''appliquer à de nombreux électeurs adultes, à qui personne ne propose de retirer le droit de vote. Pour autant, je suis convaincu qu''abaisser l''âge du vote serait une bonne décision. À seize ans, on peut déjà travailler, payer des impôts sur un salaire d''apprenti ou choisir son orientation professionnelle : il serait logique de pouvoir aussi participer aux décisions qui concernent son avenir, notamment en matière d''éducation ou de climat. En outre, voter pour la première fois au lycée, où l''on peut en discuter en classe, aiderait sans doute à prendre l''habitude de voter. Malgré les réserves, l''expérience mérite donc d''être tentée."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe14n1h041', 'practice', 'Écriture B2 : les quotas dans les entreprises', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Lisez le document, puis écrivez un paragraphe argumenté qui utilise au moins deux chiffres du document. (120 mots minimum)</p>', '<p><strong>Sujet.</strong> Faut-il imposer aux grandes entreprises un quota de 40 % de femmes parmi leurs dirigeants ? Donnez votre opinion dans un paragraphe.</p><p><strong>Document (données fictives pour l''exercice).</strong> Dans le pays de l''exercice, les femmes représentent 48 % des salariés des grandes entreprises, mais seulement 19 % des dirigeants. Dans les entreprises qui appliquent déjà un quota, cette part est passée de 15 % à 38 % en dix ans. Selon un sondage, 61 % des salariées déclarent avoir déjà renoncé à une promotion à cause de l''organisation du travail.</p><p><strong>Boîte à outils :</strong> selon • d''après • à peine • près de • plus de • ce chiffre montre que • passer de … à …</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un quota (nom masculin) : hạn ngạch, tỉ lệ bắt buộc\n• un dirigeant (nom masculin) : người lãnh đạo\n• une promotion (nom féminin) : sự thăng chức\n• renoncer à (verbe) : từ bỏ\n• gaspiller (verbe) : lãng phí","explications":"• Số liệu không tự nói: sau mỗi con số cần một câu diễn giải (« ce chiffre montre que »).\n• Đổi cách nói số cho đỡ lặp: 48 % thành « près de la moitié », 61 % thành « plus de 60 % ».","isPremium":true,"price":19000,"kyNang":"B2-PE-3","vong":"hoc","thuTu":5}'::jsonb, '2026-11-15T08:00:13.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1501g', 'b2pe14n1h041', 1, 'open', 'Écrivez votre paragraphe.', '{}'::jsonb, '{"model":"Je suis favorable aux quotas, car sans eux l''égalité dans les directions risque de prendre encore des décennies. D''après le document, les femmes représentent près de la moitié des salariés des grandes entreprises, 48 %, mais à peine 19 % des dirigeants. Ce chiffre montre que le problème ne vient pas d''un manque de candidates, mais d''un blocage au moment des promotions. Or, là où un quota existe déjà, la part des femmes dirigeantes est passée de 15 % à 38 % en dix ans : la règle a donc produit des effets rapides et mesurables. On reproche souvent aux quotas de nommer des personnes pour leur sexe plutôt que pour leurs compétences. Pourtant, quand plus de 60 % des salariées disent avoir renoncé à une promotion, il est clair que les compétences existent et qu''elles sont aujourd''hui gaspillées."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe15n1h042', 'practice', 'Écriture B2 : les jeux vidéo à l''école', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Écrivez un paragraphe qui présente l''idée opposée à la vôtre, puis la réfute point par point. (120 mots minimum)</p>', '<p><strong>Sujet.</strong> Le collège de votre quartier veut utiliser des jeux vidéo éducatifs en cours d''histoire et de sciences. Beaucoup de parents s''y opposent. Écrivez un paragraphe qui commence par présenter l''opinion des parents opposés, puis qui la réfute.</p><p><strong>Boîte à outils :</strong> selon certains • d''abord… ensuite… • c''est oublier que • contrairement à ce que l''on pense • loin de</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• détourner de (verbe) : làm xao nhãng khỏi\n• reposer sur (verbe) : dựa trên\n• une confusion (nom féminin) : sự nhầm lẫn\n• une console (nom féminin) : máy chơi game\n• décrocher (verbe) : bỏ cuộc, mất hứng học","explications":"• Trình bày ý phe kia công bằng trước khi phản bác: bài nghe có lý hơn.\n• Phản bác từng điểm theo thứ tự (d''abord, ensuite) để người đọc theo kịp.","isPremium":true,"price":19000,"kyNang":"B2-PE-3","vong":"hoc","thuTu":6}'::jsonb, '2026-11-15T08:00:14.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1501h', 'b2pe15n1h042', 1, 'open', 'Écrivez votre paragraphe.', '{}'::jsonb, '{"model":"Selon certains parents, les jeux vidéo n''ont rien à faire à l''école : les enfants y passent déjà trop de temps à la maison, et le jeu détournerait les élèves du vrai travail. Ces inquiétudes sont compréhensibles, mais elles reposent sur une confusion. D''abord, un jeu éducatif utilisé une heure par semaine avec un professeur n''a rien à voir avec des soirées entières devant une console. Ensuite, c''est oublier que le jeu peut être un vrai travail : construire une ville romaine qui doit nourrir sa population oblige à comprendre l''économie, la géographie et les choix politiques de l''époque. Contrairement à ce que l''on pense, ce type d''activité demande souvent plus de réflexion qu''un exercice classique. Loin de remplacer les cours, le jeu peut donc donner envie d''apprendre à des élèves qui décrochent."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe16n1h043', 'practice', 'Écriture B2 : un sujet, trois arguments', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Vous avez vingt minutes. Pour le sujet ci-dessous, écrivez votre position et trois arguments, chacun avec un exemple précis. Des phrases complètes, mais pas encore le texte final. (90 mots minimum)</p>', '<p><strong>Sujet.</strong> « Les villes devraient rendre les transports en commun gratuits pour tous. » Vous écrivez un article pour le journal de votre ville.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la gratuité (nom féminin) : sự miễn phí\n• le réseau (nom masculin) : mạng lưới\n• la fréquentation (nom féminin) : lượng hành khách\n• les recettes (nom féminin pluriel) : khoản thu\n• évaluer (verbe) : đánh giá","explications":"• Trong phòng thi, ba luận điểm có ví dụ là khung xương của bài 250 từ: mỗi luận điểm thành một đoạn khoảng 60 đến 70 từ.\n• Luận điểm thứ ba có thể là một giới hạn: bài sẽ cân bằng mà vẫn giữ lập trường.","isPremium":true,"price":19000,"kyNang":"B2-PE-3","vong":"on","thuTu":7}'::jsonb, '2026-11-15T08:00:15.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1501i', 'b2pe16n1h043', 1, 'open', 'Écrivez votre position et vos trois arguments.', '{}'::jsonb, '{"model":"Position : je suis favorable à la gratuité, mais seulement si elle s''accompagne d''une amélioration du réseau.\nArgument 1 : moins de voitures en ville. Exemple : à Dunkerque, la fréquentation des bus a fortement augmenté après la mise en place de la gratuité.\nArgument 2 : une mesure sociale. Exemple : un étudiant qui paie trente euros par mois d''abonnement pourrait consacrer cette somme à ses repas.\nArgument 3 (avec une limite) : la gratuité coûte cher à la ville. Exemple : les recettes des tickets disparaissent, il faut donc les remplacer, par exemple par une taxe sur les grandes entreprises.\nConclusion prévue : commencer par la gratuité le week-end, puis évaluer."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe17n1h044', 'practice', 'Écriture B2 : essai de 250 mots', 'B2', array['Production écrite']::text[], 'practice', null, 60, '<p>Comme le jour de l''examen : vous avez 60 minutes. Lisez le sujet et écrivez votre texte. (250 mots minimum)</p>', '<p><strong>Sujet.</strong> Un magazine destiné aux parents publie un dossier intitulé « Faut-il interdire le smartphone avant 15 ans ? ». Vous écrivez un article pour ce dossier : vous donnez votre opinion de façon argumentée, en vous appuyant sur des exemples précis.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• céder (verbe) : nhượng bộ\n• le harcèlement (nom masculin) : sự quấy rối, bắt nạt\n• contre-productif (adjectif) : phản tác dụng\n• la modération (nom féminin) : sự điều độ\n• bannir (verbe) : cấm tiệt","explications":"• Chia 60 phút: 10 phút phân tích đề và lập dàn ý, 40 phút viết, 10 phút đọc lại và đếm từ.\n• Bài báo có tiêu đề; mở bài đặt vấn đề và nêu lập trường; mỗi đoạn một ý; kết bài tóm lại và mở rộng.","isPremium":true,"price":19000,"kyNang":"B2-PE-3","vong":"chot","thuTu":8}'::jsonb, '2026-11-15T08:00:16.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1501j', 'b2pe17n1h044', 1, 'open', 'Écrivez votre article.', '{}'::jsonb, '{"model":"Le smartphone avant 15 ans : interdire ou apprendre ?\n\nÀ dix ans, plus d''un enfant sur deux possède déjà son propre téléphone, et beaucoup de parents se demandent s''ils ont eu raison de céder. Faut-il pour autant interdire le smartphone avant quinze ans ? Je ne le crois pas, même si des règles strictes me semblent indispensables.\n\nCertes, les dangers sont réels. Les écrans réduisent le temps de sommeil, et les réseaux sociaux exposent les plus jeunes au harcèlement ou à des images violentes. Une enseignante de collège me racontait récemment que plusieurs de ses élèves arrivaient épuisés le matin après avoir passé une partie de la nuit sur leur téléphone.\n\nPourtant, une interdiction totale serait difficile à appliquer et sans doute contre-productive. Un adolescent privé de téléphone se sentira exclu de son groupe d''amis, qui s''organise presque entièrement par messages. De plus, interdire ne permet pas d''apprendre : à quinze ans, l''enfant recevra un appareil sans jamais avoir appris à s''en servir avec modération.\n\nIl me paraît donc plus efficace d''accompagner progressivement. On peut par exemple donner d''abord un téléphone simple, sans internet, puis un smartphone avec des applications limitées. Fixer des règles claires, comme laisser l''appareil hors de la chambre la nuit, protège le sommeil sans couper l''enfant des autres. Ces règles seront d''autant mieux respectées que les parents les appliqueront eux-mêmes.\n\nEn somme, le smartphone n''est ni un ennemi à bannir ni un jouet à offrir sans condition. C''est un outil qu''il faut apprendre à maîtriser, et ce rôle revient d''abord aux parents."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe18n1h045', 'practice', 'Écriture B2 : une transition réussie', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Choisissez la meilleure phrase de transition, remettez un passage dans l''ordre, puis écrivez vos propres transitions.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une transition (nom féminin) : câu chuyển đoạn\n• face à ce constat (expression) : trước thực trạng đó\n• en définitive (locution) : rốt cuộc, tóm lại\n• encadrer (verbe) : quản lý, đặt khuôn khổ\n• trompeur (adjectif) : gây hiểu lầm","explications":"• Câu chuyển đoạn tốt nhắc lại ý đoạn trước bằng vài chữ, rồi báo trước ý đoạn sau.\n• Chọn từ nối theo QUAN HỆ giữa hai đoạn: ngược ý (toutefois), hệ quả (c''est pourquoi), thêm ý (en outre), vấn đề sang giải pháp (face à ce constat).","isPremium":true,"price":19000,"kyNang":"B2-PE-4","vong":"hoc","thuTu":3}'::jsonb, '2026-11-15T08:00:17.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1501k', 'b2pe18n1h045', 1, 'qcm', 'Paragraphe 1 : les avantages du vélo en ville. Paragraphe 2 : les dangers pour les cyclistes. Quelle transition convient ?', '{"options":["Si le vélo présente de nombreux avantages, il n''est pas pour autant sans risque.","Par conséquent, les cyclistes sont souvent en danger dans les grandes villes.","Le vélo présente de nombreux avantages, et il en présente encore beaucoup d''autres en ville."]}'::jsonb, '{"answer":0}'::jsonb, '« Si … il n''est pas pour autant »: tóm ý đoạn trước rồi mở ý ngược lại của đoạn sau. « Par conséquent » sai quan hệ (không phải hệ quả).'), ('qmwh84n1501l', 'b2pe18n1h045', 2, 'qcm', 'Paragraphe 1 : le problème du gaspillage alimentaire. Paragraphe 2 : des solutions. Quelle transition convient ?', '{"options":["Face à ce constat, plusieurs solutions peuvent être envisagées.","Ensuite, le gaspillage alimentaire existe aussi dans les cantines scolaires.","En revanche, le gaspillage alimentaire n''est pas un véritable problème."]}'::jsonb, '{"answer":0}'::jsonb, '« Face à ce constat »: gói lại vấn đề vừa nêu và chuyển sang giải pháp.'), ('qmwh84n1501m', 'b2pe18n1h045', 3, 'qcm', 'Quelle phrase introduit le mieux la conclusion ?', '{"options":["Premièrement, il faut définir ce qu''est vraiment le télétravail.","En définitive, le télétravail est une chance, à condition d''être bien encadré.","De plus, le télétravail permet aussi de faire des économies de transport et de temps."]}'::jsonb, '{"answer":1}'::jsonb, '« En définitive » mở kết bài và tóm lập trường. « De plus », « Premièrement » mở ý mới, không phải kết.'), ('qmwh84n1501n', 'b2pe18n1h045', 4, 'ordre', 'Remettez dans l''ordre ce passage entre deux paragraphes.', '{"elements":[{"id":"emwh84n1501r","texte":"C''est notamment le cas dans les centres historiques les plus visités."},{"id":"emwh84n1501p","texte":"Cependant, ce succès a un prix."},{"id":"emwh84n1501o","texte":"Le tourisme apporte donc des emplois et des revenus aux régions qui l''accueillent."},{"id":"emwh84n1501q","texte":"Dans plusieurs villes, les habitants ne parviennent plus à se loger à cause des locations touristiques."}]}'::jsonb, '{"elements":[{"id":"emwh84n1501o","texte":"Le tourisme apporte donc des emplois et des revenus aux régions qui l''accueillent."},{"id":"emwh84n1501p","texte":"Cependant, ce succès a un prix."},{"id":"emwh84n1501q","texte":"Dans plusieurs villes, les habitants ne parviennent plus à se loger à cause des locations touristiques."},{"id":"emwh84n1501r","texte":"C''est notamment le cas dans les centres historiques les plus visités."}]}'::jsonb, 'Câu tổng kết đoạn trước (« donc »), câu chuyển hướng ngắn (« Cependant »), câu chủ đề đoạn mới, rồi ví dụ (« C''est notamment le cas »).'), ('qmwh84n1501s', 'b2pe18n1h045', 5, 'open', 'Paragraphe 1 : les réseaux sociaux aident les associations à se faire connaître. Paragraphe 2 : ils diffusent aussi de fausses informations. Écrivez la phrase de transition. (20 mots minimum)', '{}'::jsonb, '{"model":"Toutefois, si les réseaux sociaux offrent une visibilité précieuse aux associations, ils servent aussi à diffuser des informations fausses ou trompeuses."}'::jsonb, null), ('qmwh84n1501t', 'b2pe18n1h045', 6, 'open', 'Paragraphe 1 : le coût élevé des études à l''étranger. Paragraphe 2 : les bourses et les programmes d''échange. Écrivez la phrase de transition. (20 mots minimum)', '{}'::jsonb, '{"model":"Ce coût élevé ne doit pourtant pas décourager les étudiants, car il existe des bourses et des programmes d''échange qui réduisent fortement les dépenses."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe19n1h046', 'practice', 'Écriture B2 : reprendre sans répéter', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Complétez avec un pronom ou un mot de reprise pour éviter les répétitions, puis choisissez la meilleure version.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la reprise (nom féminin) : sự nhắc lại (bằng từ khác)\n• la méfiance (nom féminin) : sự nghi ngại\n• ce dernier (pronom) : người, vật vừa nhắc sau cùng\n• l''isolation (nom féminin) : cách nhiệt\n• autrefois (adverbe) : ngày trước","explications":"• Bốn cách tránh lặp: đại từ (le, y, en), đại từ chỉ định (celui-ci, ce dernier), từ khái quát (ce moyen de transport), danh hoá (cette réduction).\n• Kiểm tra đại từ có chỉ rõ một người không: hai người cùng giống thì dùng « ce dernier ».","isPremium":true,"price":19000,"kyNang":"B2-PE-4","vong":"hoc","thuTu":4}'::jsonb, '2026-11-15T08:00:18.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1501u', 'b2pe19n1h046', 1, 'fill', 'Le maire a présenté son projet. Les habitants ______ ont accueilli avec méfiance. (pronom)', '{}'::jsonb, '{"accepted":"l''|l’"}'::jsonb, 'Thay « son projet » (tân ngữ trực tiếp, giống đực, đứng trước nguyên âm): l''.'), ('qmwh84n1501v', 'b2pe19n1h046', 2, 'fill', 'Beaucoup de jeunes rêvent de partir à l''étranger, mais peu ______ vont vraiment. (pronom de lieu)', '{}'::jsonb, '{"accepted":"y"}'::jsonb, '“y” thay cho « à l''étranger » (nơi chốn).'), ('qmwh84n1501w', 'b2pe19n1h046', 3, 'fill', 'On parle beaucoup du télétravail, mais on ______ connaît mal les effets à long terme. (pronom)', '{}'::jsonb, '{"accepted":"en"}'::jsonb, '“en” thay cho « du télétravail » (de + danh từ): on connaît mal les effets du télétravail.'), ('qmwh84n1501x', 'b2pe19n1h046', 4, 'fill', 'La ministre a rencontré le directeur de l''hôpital. Ce ______ lui a demandé plus de moyens. (= le directeur, le dernier nommé)', '{}'::jsonb, '{"accepted":"dernier"}'::jsonb, '“ce dernier” chỉ người được nhắc sau cùng (le directeur), tránh « il » mơ hồ (có thể hiểu là bà bộ trưởng).'), ('qmwh84n1501y', 'b2pe19n1h046', 5, 'fill', 'Les voitures électriques et les voitures à essence n''ont pas le même coût. ______-ci sont plus chères à l''achat. (= les voitures électriques)', '{}'::jsonb, '{"accepted":"Celles|celles"}'::jsonb, '“Celles-ci” thay cho danh từ giống cái số nhiều; ở đây chỉ vế được nhắc tới (les voitures électriques).'), ('qmwh84n1501z', 'b2pe19n1h046', 6, 'fill', 'Le gouvernement veut réduire la consommation d''énergie. Cette ______ passe par une meilleure isolation des logements. (nom tiré de « réduire »)', '{}'::jsonb, '{"accepted":"réduction"}'::jsonb, 'Danh hoá động từ để nhắc lại ý: réduire thành “cette réduction”.'), ('qmwh84n15020', 'b2pe19n1h046', 7, 'qcm', 'Quelle version évite le mieux la répétition ?', '{"options":["Les bibliothèques changent. Les bibliothèques accueillent aujourd''hui des ateliers, des concerts et des expositions.","Les bibliothèques changent. Elles, les bibliothèques, accueillent des ateliers et des concerts.","Les bibliothèques changent. Ces lieux autrefois silencieux accueillent aujourd''hui des ateliers et des concerts."]}'::jsonb, '{"answer":2}'::jsonb, '« Ces lieux autrefois silencieux »: từ thay thế mang thêm thông tin, thay vì lặp nguyên « les bibliothèques ».'), ('qmwh84n15021', 'b2pe19n1h046', 8, 'qcm', '« Le vélo est bon pour la santé. Le vélo est aussi écologique. » Meilleure reprise :', '{"options":["Le vélo est bon pour la santé ; ce moyen de transport est aussi écologique.","Le vélo est bon pour la santé ; celui-ci il est aussi écologique.","Le vélo est bon pour la santé ; le vélo, il est aussi très écologique en plus de ça."]}'::jsonb, '{"answer":0}'::jsonb, '« ce moyen de transport »: từ khái quát thay cho « le vélo ». Hai phương án kia vừa lặp vừa thừa chủ ngữ « il ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe20n1h047', 'practice', 'Écriture B2 : reconstituez le texte', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Chaque paragraphe vient d''un texte argumenté, mais les phrases sont dans le désordre. Remettez-les dans l''ordre.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• jetable (adjectif) : dùng một lần rồi bỏ\n• négocier (verbe) : thương lượng\n• autonome (adjectif) : tự hành\n• nuancer (verbe) : nói cho có sắc thái\n• tous les maux (expression) : mọi điều tệ hại","explications":"• Từ nối là manh mối: « en effet » đứng sau câu nó giải thích, « par exemple » sau luận điểm, « donc », « en somme » ở cuối.\n• Câu có « ce », « cette », « ces » + danh từ thường nhắc lại câu ngay trước nó.","isPremium":true,"price":19000,"kyNang":"B2-PE-4","vong":"on","thuTu":5}'::jsonb, '2026-11-15T08:00:19.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n15022', 'b2pe20n1h047', 1, 'ordre', 'Introduction d''un article', '{"elements":[{"id":"emwh84n15024","texte":"Cette mode jetable pose un grave problème environnemental."},{"id":"emwh84n15026","texte":"Nous verrons que d''autres solutions, plus réalistes, existent."},{"id":"emwh84n15025","texte":"Faut-il pour autant renoncer à acheter des vêtements neufs ?"},{"id":"emwh84n15023","texte":"Chaque année, des millions de tonnes de vêtements finissent à la poubelle."}]}'::jsonb, '{"elements":[{"id":"emwh84n15023","texte":"Chaque année, des millions de tonnes de vêtements finissent à la poubelle."},{"id":"emwh84n15024","texte":"Cette mode jetable pose un grave problème environnemental."},{"id":"emwh84n15025","texte":"Faut-il pour autant renoncer à acheter des vêtements neufs ?"},{"id":"emwh84n15026","texte":"Nous verrons que d''autres solutions, plus réalistes, existent."}]}'::jsonb, 'Mở bài: sự việc gây chú ý, vấn đề (« Cette mode jetable »), câu hỏi đặt ra, rồi báo trước hướng bài (« Nous verrons »).'), ('qmwh84n15027', 'b2pe20n1h047', 2, 'ordre', 'Paragraphe avec exemple', '{"elements":[{"id":"emwh84n1502b","texte":"Ces qualités seront précieuses dans la vie professionnelle."},{"id":"emwh84n1502a","texte":"Par exemple, lors d''un projet de groupe, chaque étudiant doit défendre ses idées tout en tenant compte de celles des autres."},{"id":"emwh84n15028","texte":"Le travail en équipe développe des compétences recherchées."},{"id":"emwh84n15029","texte":"En effet, il oblige à écouter, à négocier et à partager les tâches."}]}'::jsonb, '{"elements":[{"id":"emwh84n15028","texte":"Le travail en équipe développe des compétences recherchées."},{"id":"emwh84n15029","texte":"En effet, il oblige à écouter, à négocier et à partager les tâches."},{"id":"emwh84n1502a","texte":"Par exemple, lors d''un projet de groupe, chaque étudiant doit défendre ses idées tout en tenant compte de celles des autres."},{"id":"emwh84n1502b","texte":"Ces qualités seront précieuses dans la vie professionnelle."}]}'::jsonb, 'Luận điểm, giải thích (« En effet »), ví dụ (« Par exemple »), câu rút ra (« Ces qualités »).'), ('qmwh84n1502c', 'b2pe20n1h047', 3, 'ordre', 'Paragraphe avec concession', '{"elements":[{"id":"emwh84n1502g","texte":"Tant que cette question restera sans réponse, la prudence s''impose."},{"id":"emwh84n1502d","texte":"Il est vrai que les voitures autonomes pourraient réduire les accidents."},{"id":"emwh84n1502e","texte":"La plupart des accidents sont en effet dus à des erreurs humaines."},{"id":"emwh84n1502f","texte":"Mais qui sera responsable si une voiture sans conducteur provoque un accident ?"}]}'::jsonb, '{"elements":[{"id":"emwh84n1502d","texte":"Il est vrai que les voitures autonomes pourraient réduire les accidents."},{"id":"emwh84n1502e","texte":"La plupart des accidents sont en effet dus à des erreurs humaines."},{"id":"emwh84n1502f","texte":"Mais qui sera responsable si une voiture sans conducteur provoque un accident ?"},{"id":"emwh84n1502g","texte":"Tant que cette question restera sans réponse, la prudence s''impose."}]}'::jsonb, 'Nhượng bộ (« Il est vrai que »), lý do của nhượng bộ, phản bác (« Mais »), kết luận đoạn.'), ('qmwh84n1502h', 'b2pe20n1h047', 4, 'ordre', 'Paragraphe avec chiffres', '{"elements":[{"id":"emwh84n1502i","texte":"Les jeunes lisent-ils moins qu''avant ?"},{"id":"emwh84n1502j","texte":"Selon une enquête récente, ils lisent en moyenne moins de livres que leurs parents au même âge."},{"id":"emwh84n1502k","texte":"Ce chiffre doit pourtant être nuancé."},{"id":"emwh84n1502l","texte":"Ils lisent en effet beaucoup sur écran : articles, bandes dessinées numériques ou romans en ligne."}]}'::jsonb, '{"elements":[{"id":"emwh84n1502i","texte":"Les jeunes lisent-ils moins qu''avant ?"},{"id":"emwh84n1502j","texte":"Selon une enquête récente, ils lisent en moyenne moins de livres que leurs parents au même âge."},{"id":"emwh84n1502k","texte":"Ce chiffre doit pourtant être nuancé."},{"id":"emwh84n1502l","texte":"Ils lisent en effet beaucoup sur écran : articles, bandes dessinées numériques ou romans en ligne."}]}'::jsonb, 'Câu hỏi mở đoạn, số liệu (« Selon une enquête »), câu nhận định lại (« doit pourtant être nuancé »), giải thích (« en effet »).'), ('qmwh84n1502m', 'b2pe20n1h047', 5, 'ordre', 'Paragraphe de réfutation', '{"elements":[{"id":"emwh84n1502n","texte":"On entend souvent que les jeux vidéo rendent violent."},{"id":"emwh84n1502p","texte":"Au contraire, certains jeux développent la coopération et la patience."},{"id":"emwh84n1502q","texte":"Il serait donc injuste d''accuser les jeux de tous les maux de la société."},{"id":"emwh84n1502o","texte":"Pourtant, aucune étude sérieuse n''a démontré ce lien de façon claire."}]}'::jsonb, '{"elements":[{"id":"emwh84n1502n","texte":"On entend souvent que les jeux vidéo rendent violent."},{"id":"emwh84n1502o","texte":"Pourtant, aucune étude sérieuse n''a démontré ce lien de façon claire."},{"id":"emwh84n1502p","texte":"Au contraire, certains jeux développent la coopération et la patience."},{"id":"emwh84n1502q","texte":"Il serait donc injuste d''accuser les jeux de tous les maux de la société."}]}'::jsonb, 'Ý phổ biến cần bác (« On entend souvent »), phản bác (« Pourtant »), ý ngược lại (« Au contraire »), kết luận (« donc »).'), ('qmwh84n1502r', 'b2pe20n1h047', 6, 'ordre', 'Conclusion d''un article', '{"elements":[{"id":"emwh84n1502s","texte":"En somme, le télétravail n''est ni un paradis ni un enfer."},{"id":"emwh84n1502t","texte":"Bien organisé, il améliore la qualité de vie des salariés."},{"id":"emwh84n1502v","texte":"Reste à savoir si les entreprises sauront trouver le bon équilibre."},{"id":"emwh84n1502u","texte":"Mal encadré, il peut au contraire les isoler."}]}'::jsonb, '{"elements":[{"id":"emwh84n1502s","texte":"En somme, le télétravail n''est ni un paradis ni un enfer."},{"id":"emwh84n1502t","texte":"Bien organisé, il améliore la qualité de vie des salariés."},{"id":"emwh84n1502u","texte":"Mal encadré, il peut au contraire les isoler."},{"id":"emwh84n1502v","texte":"Reste à savoir si les entreprises sauront trouver le bon équilibre."}]}'::jsonb, 'Kết bài: tóm lập trường (« En somme »), hai vế cân bằng (« Bien organisé » / « Mal encadré »), câu mở rộng cuối (« Reste à savoir »).')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe21n1i048', 'practice', 'Écriture B2 : rendez ce texte cohérent', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Ce paragraphe contient de bonnes idées, mais il est décousu : pas de mots de liaison, des répétitions, un ordre peu logique. Réécrivez-le pour le rendre cohérent. (150 mots minimum)</p>', '<p>Les cantines scolaires devraient proposer plus de repas végétariens. Les repas végétariens coûtent moins cher. Les enfants mangent trop de viande. Les médecins disent que les enfants mangent trop de viande. Certains parents ont peur. Les parents ont peur que les enfants manquent de protéines. Les légumineuses contiennent beaucoup de protéines. Les lentilles et les pois chiches sont des légumineuses. L''élevage produit beaucoup de gaz à effet de serre. Les cantines servent des millions de repas. Les cantines peuvent avoir un effet important. Il faut former les cuisiniers. Les repas végétariens doivent être bons. Sinon les enfants ne mangeront pas les repas végétariens.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• décousu (adjectif) : rời rạc\n• une légumineuse (nom féminin) : cây họ đậu\n• l''élevage (nom masculin) : chăn nuôi\n• appétissant (adjectif) : hấp dẫn, ngon mắt\n• faute de quoi (locution) : nếu không thì","explications":"• Trước khi viết lại, gom ý thành nhóm: sức khoẻ, môi trường, chi phí, ý lo ngại và câu trả lời, điều kiện thành công.\n• Mỗi nhóm một từ nối mở đầu; ý lo ngại đi với « certes … pourtant ».","isPremium":true,"price":19000,"kyNang":"B2-PE-4","vong":"chot","thuTu":6}'::jsonb, '2026-11-15T08:00:20.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1502w', 'b2pe21n1i048', 1, 'open', 'Écrivez la version cohérente du paragraphe.', '{}'::jsonb, '{"model":"Les cantines scolaires devraient proposer davantage de repas végétariens, et ce pour plusieurs raisons. D''abord, d''après les médecins, les enfants consomment aujourd''hui trop de viande ; réduire cette part serait donc bénéfique pour leur santé. Ensuite, l''enjeu est aussi écologique. En effet, l''élevage produit une grande quantité de gaz à effet de serre, et comme les cantines servent chaque jour des millions de repas, leur choix peut avoir un effet considérable. De plus, ces menus coûtent moins cher, ce qui permettrait d''améliorer la qualité des autres produits. Certes, certains parents craignent que leurs enfants manquent de protéines. Cette inquiétude est pourtant peu fondée, puisque les légumineuses, comme les lentilles ou les pois chiches, en contiennent beaucoup. Encore faut-il que ces plats soient appétissants : c''est pourquoi il est indispensable de former les cuisiniers, faute de quoi les élèves laisseront leur assiette pleine et la mesure perdrait alors tout son sens."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe22n1i049', 'practice', 'Écriture B2 : bien que, quoique, malgré', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Choisissez la bonne structure, complétez avec le verbe au bon mode, puis transformez les phrases en phrases de concession.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la concession (nom féminin) : sự nhượng bộ\n• malgré (préposition) : mặc dù (+ danh từ)\n• quoique (conjonction) : mặc dù (+ subjonctif)\n• pourtant (adverbe) : tuy vậy\n• compétent (adjectif) : có năng lực","explications":"• Bien que, quoique + subjonctif; même si + indicatif; malgré + danh từ; pourtant, cependant nối hai câu.\n• Đổi « bien que + mệnh đề » thành « malgré + danh từ » cần danh hoá: les médecins conseillent thành « les conseils des médecins ».","isPremium":true,"price":19000,"kyNang":"B2-PE-5","vong":"hoc","thuTu":5}'::jsonb, '2026-11-15T08:00:21.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1502x', 'b2pe22n1i049', 1, 'qcm', '______ la pluie, le marché a attiré beaucoup de monde.', '{"options":["Malgré","Quoique","Bien que"]}'::jsonb, '{"answer":0}'::jsonb, '« Malgré » + danh từ (la pluie). “Bien que”, « quoique » phải theo sau là một mệnh đề có động từ.'), ('qmwh84n1502y', 'b2pe22n1i049', 2, 'qcm', 'Bien qu''il ______ beaucoup travaillé, il n''a pas réussi l''examen.', '{"options":["avait","a","ait"]}'::jsonb, '{"answer":2}'::jsonb, '“Bien que” luôn đi với subjonctif: “qu''il ait travaillé” (subjonctif passé).'), ('qmwh84n1502z', 'b2pe22n1i049', 3, 'qcm', 'Quelle phrase est correcte ?', '{"options":["Même si le projet est coûteux, il reste nécessaire.","Même si le projet serait coûteux, il reste nécessaire.","Même si le projet soit coûteux, il reste nécessaire."]}'::jsonb, '{"answer":0}'::jsonb, '« Même si » đi với indicatif, không bao giờ với subjonctif hay conditionnel.'), ('qmwh84n15030', 'b2pe22n1i049', 4, 'qcm', '« Elle est très compétente ; ______, elle n''a pas obtenu le poste. »', '{"options":["pourtant","parce que","donc"]}'::jsonb, '{"answer":0}'::jsonb, '« pourtant »: nhượng bộ giữa hai câu độc lập. « parce que » chỉ nguyên nhân, « donc » chỉ hệ quả.'), ('qmwh84n15031', 'b2pe22n1i049', 5, 'fill', 'Quoique ce livre ______ (être) difficile, je le recommande à tous les lycéens.', '{}'::jsonb, '{"accepted":"soit"}'::jsonb, '« Quoique » + subjonctif: “ce livre soit”.'), ('qmwh84n15032', 'b2pe22n1i049', 6, 'fill', 'Bien que nous ______ (partir) tôt, nous sommes arrivés en retard. (subjonctif passé, une forme composée : deux mots)', '{}'::jsonb, '{"accepted":"soyons partis"}'::jsonb, '« partir » dùng être: subjonctif passé là “que nous soyons partis”.'), ('qmwh84n15033', 'b2pe22n1i049', 7, 'open', 'Transformez avec « bien que » : « Le loyer est élevé. Beaucoup d''étudiants veulent habiter dans le centre. » (8 mots minimum)', '{}'::jsonb, '{"model":"Bien que le loyer soit élevé, beaucoup d''étudiants veulent habiter dans le centre."}'::jsonb, null), ('qmwh84n15034', 'b2pe22n1i049', 8, 'open', 'Transformez avec « malgré » : « Les médecins ont donné des conseils. Beaucoup de gens continuent à fumer. » (8 mots minimum)', '{}'::jsonb, '{"model":"Malgré les conseils des médecins, beaucoup de gens continuent à fumer."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe23n1i04a', 'practice', 'Écriture B2 : si j''avais su', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Complétez les phrases hypothétiques avec le verbe au bon temps, puis choisissez la bonne réponse.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une hypothèse (nom féminin) : giả thuyết, giả định\n• une piste cyclable (nom féminin) : làn xe đạp\n• au cas où (locution) : phòng khi\n• le regret (nom masculin) : sự tiếc nuối\n• un poste (nom masculin) : vị trí công việc","explications":"• Ba khuôn: si + présent → futur; si + imparfait → conditionnel présent; si + plus-que-parfait → conditionnel passé.\n• Câu hỗn hợp B2 trộn hai khuôn cuối khi điều kiện và kết quả khác thời điểm.","isPremium":true,"price":19000,"kyNang":"B2-PE-5","vong":"hoc","thuTu":6}'::jsonb, '2026-11-15T08:00:22.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n15035', 'b2pe23n1i04a', 1, 'fill', 'Si la ville construisait des pistes cyclables, plus d''habitants ______ (prendre) le vélo.', '{}'::jsonb, '{"accepted":"prendraient"}'::jsonb, 'Si + imparfait, mệnh đề chính conditionnel présent: prendraient.'), ('qmwh84n15036', 'b2pe23n1i04a', 2, 'fill', 'Si j''avais su que le musée était fermé, je ______ (rester) à la maison. (conditionnel passé : deux mots)', '{}'::jsonb, '{"accepted":"serais resté|serais restée"}'::jsonb, 'Si + plus-que-parfait, mệnh đề chính conditionnel passé: je serais resté(e).'), ('qmwh84n15037', 'b2pe23n1i04a', 3, 'fill', 'Si tu ______ (finir) ton rapport avant midi, nous pourrons le relire ensemble.', '{}'::jsonb, '{"accepted":"finis"}'::jsonb, 'Si + présent, mệnh đề chính futur: điều kiện có thật trong tương lai gần.'), ('qmwh84n15038', 'b2pe23n1i04a', 4, 'fill', 'Au cas où le train ______ (être) en retard, appelez-moi.', '{}'::jsonb, '{"accepted":"serait"}'::jsonb, '« Au cas où » + conditionnel (không phải imparfait như sau « si »).'), ('qmwh84n15039', 'b2pe23n1i04a', 5, 'qcm', 'Quelle phrase exprime un regret sur le passé ?', '{"options":["Si nous agissons plus tôt, la forêt sera sauvée.","Si nous agissions plus tôt, la forêt serait sauvée.","Si nous avions agi plus tôt, la forêt aurait été sauvée."]}'::jsonb, '{"answer":2}'::jsonb, 'Si + plus-que-parfait + conditionnel passé (« aurait été sauvée »): điều đã không xảy ra trong quá khứ.'), ('qmwh84n1503a', 'b2pe23n1i04a', 6, 'qcm', 'Quelle phrase est incorrecte ?', '{"options":["Si j''ai le temps, je lirai davantage.","Si j''aurais le temps, je lirais davantage.","Si j''avais le temps, je lirais davantage."]}'::jsonb, '{"answer":1}'::jsonb, 'Không bao giờ dùng conditionnel ngay sau « si » chỉ điều kiện: « si j''aurais » là lỗi rất hay gặp.'), ('qmwh84n1503b', 'b2pe23n1i04a', 7, 'qcm', '« À ta place, j''______ ce poste. »', '{"options":["accepterais","accepterai","acceptais"]}'::jsonb, '{"answer":0}'::jsonb, '« À ta place » là giả định ngầm (= si j''étais toi): dùng conditionnel « accepterais ».'), ('qmwh84n1503c', 'b2pe23n1i04a', 8, 'qcm', 'Quelle phrase exprime une hypothèse sur le présent dont la conséquence est passée ?', '{"options":["Si elle parle français, elle obtiendra ce poste l''an prochain.","Si elle parlait français, elle aurait obtenu ce poste l''an dernier.","Si elle avait parlé français, elle obtiendrait ce poste demain."]}'::jsonb, '{"answer":1}'::jsonb, 'Giả định hỗn hợp: điều kiện hiện tại (« parlait », cô ấy vẫn không nói được) dẫn tới kết quả quá khứ (« aurait obtenu … l''an dernier »).')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe24n1i04b', 'practice', 'Écriture B2 : choisissez la structure', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Cet exercice mélange les structures des leçons précédentes : concession, hypothèse, subjonctif, relatifs composés, nominalisation.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• tenir à (verbe) : coi trọng, gắn bó với\n• la fermeture (nom féminin) : việc đóng cửa\n• en dépit de (locution) : bất chấp\n• une réforme (nom féminin) : cải cách\n• la construction (nom féminin) : việc xây dựng","explications":"• Nhận diện câu trước khi chọn: sau từ này cần danh từ hay mệnh đề? Động từ chính đòi giới từ nào?\n• Danh hoá và mệnh đề quan hệ phức (auquel, avec laquelle) là hai dấu hiệu B2 dễ ghi điểm nhất trong bài viết.","isPremium":true,"price":19000,"kyNang":"B2-PE-5","vong":"on","thuTu":7}'::jsonb, '2026-11-15T08:00:23.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1503d', 'b2pe24n1i04b', 1, 'qcm', 'C''est un projet ______ la mairie tient beaucoup.', '{"options":["auquel","lequel","dont"]}'::jsonb, '{"answer":0}'::jsonb, '“tenir à quelque chose”: à + lequel = « auquel ».'), ('qmwh84n1503e', 'b2pe24n1i04b', 2, 'qcm', 'Il faut que les élèves ______ ce texte avant jeudi.', '{"options":["lisaient","liront","lisent"]}'::jsonb, '{"answer":2}'::jsonb, '« Il faut que » + subjonctif: “qu''ils lisent”.'), ('qmwh84n1503f', 'b2pe24n1i04b', 3, 'qcm', 'La ville a annoncé ______ de la piscine pour l''été.', '{"options":["la fermeture","qu''elle ferme","fermer"]}'::jsonb, '{"answer":0}'::jsonb, 'Sau “annoncer” + mạo từ là danh từ: danh hoá « fermer » thành « la fermeture ».'), ('qmwh84n1503g', 'b2pe24n1i04b', 4, 'qcm', '______ ses efforts, il n''a pas obtenu son diplôme.', '{"options":["En dépit de","Bien que","Même si"]}'::jsonb, '{"answer":0}'::jsonb, '« En dépit de » + danh từ (= malgré). “Bien que”, « même si » cần mệnh đề có động từ.'), ('qmwh84n1503h', 'b2pe24n1i04b', 5, 'qcm', 'Voici l''association ______ laquelle nous avons organisé le festival.', '{"options":["avec","que","dont"]}'::jsonb, '{"answer":0}'::jsonb, '“organiser avec une association”: giới từ + lequel = “avec laquelle”.'), ('qmwh84n1503i', 'b2pe24n1i04b', 6, 'qcm', 'Je regrette que vous ______ partir si tôt hier soir.', '{"options":["avez dû","ayez dû","deviez"]}'::jsonb, '{"answer":1}'::jsonb, '« Je regrette que » + subjonctif; việc đã xảy ra (hier soir) nên dùng subjonctif passé « ayez dû ».'), ('qmwh84n1503j', 'b2pe24n1i04b', 7, 'fill', 'Si les loyers ______ (baisser), les jeunes quitteraient moins la ville.', '{}'::jsonb, '{"accepted":"baissaient"}'::jsonb, 'Si + imparfait, mệnh đề chính conditionnel (quitteraient).'), ('qmwh84n1503k', 'b2pe24n1i04b', 8, 'fill', 'C''est la raison pour ______ je refuse ce projet.', '{}'::jsonb, '{"accepted":"laquelle"}'::jsonb, '“pour une raison”: pour + laquelle (la raison, giống cái).'), ('qmwh84n1503l', 'b2pe24n1i04b', 9, 'fill', 'Bien que la réforme ______ (être) nécessaire, elle a été mal expliquée.', '{}'::jsonb, '{"accepted":"soit|ait été"}'::jsonb, '“Bien que” + subjonctif: “soit” (hoặc “ait été” nếu nói về quá khứ).'), ('qmwh84n1503m', 'b2pe24n1i04b', 10, 'fill', 'Les habitants demandent ______ de nouvelles écoles. (nom tiré de « construire », avec l''article)', '{}'::jsonb, '{"accepted":"la construction"}'::jsonb, 'Danh hoá « construire » thành “la construction”.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2pe25n1i04c', 'practice', 'Écriture B2 : montez au niveau B2', 'B2', array['Production écrite']::text[], 'practice', null, null, '<p>Ce paragraphe est correct mais simple (niveau B1). Réécrivez-le au niveau B2 : utilisez au moins une concession, une hypothèse, un pronom relatif composé et une nominalisation, sans changer les idées. (150 mots minimum)</p>', '<p>Je pense que les villes doivent planter plus d''arbres. Les arbres sont importants. En été, il fait très chaud dans les villes. Les arbres donnent de l''ombre et la température baisse. Les arbres coûtent cher. Il faut aussi les entretenir. Mais c''est une bonne chose pour les habitants. Dans ma ville, on a planté des arbres dans une rue. Maintenant, les gens se promènent plus dans cette rue. Les commerçants sont contents. Les villes doivent faire cela partout. Si elles ne font rien, la vie en ville va devenir difficile.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une fournaise (nom féminin) : lò lửa, nơi nóng hừng hực\n• procurer (verbe) : mang lại\n• la végétalisation (nom féminin) : việc phủ xanh\n• un riverain (nom masculin) : cư dân sống dọc phố\n• s''attarder (verbe) : nán lại","explications":"• Danh hoá (la plantation, l''entretien, la végétalisation) gộp nhiều câu ngắn thành một câu chặt chẽ.\n• Nâng cấp không phải là thêm chữ cho dài: mỗi cấu trúc phức phải nối hai ý có quan hệ thật (nhượng bộ, điều kiện).","isPremium":true,"price":19000,"kyNang":"B2-PE-5","vong":"chot","thuTu":8}'::jsonb, '2026-11-15T08:00:24.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh84n1503n', 'b2pe25n1i04c', 1, 'open', 'Écrivez la version B2 du paragraphe.', '{}'::jsonb, '{"model":"À mon sens, la plantation massive d''arbres devrait devenir une priorité pour les villes. Lors des vagues de chaleur, de plus en plus fréquentes, les centres urbains se transforment en véritables fournaises ; or, les arbres, grâce à l''ombre qu''ils procurent et à l''humidité qu''ils libèrent, permettent de faire baisser sensiblement la température. Bien que leur plantation et leur entretien représentent un coût non négligeable, il s''agit d''un investissement dont les habitants tirent rapidement profit. Dans ma ville, par exemple, la végétalisation d''une rue commerçante, à laquelle beaucoup de riverains étaient au départ hostiles, a profondément changé le quartier : les passants s''y attardent davantage et les commerçants se félicitent de l''augmentation de leur fréquentation. Si les municipalités généralisaient ce type d''aménagement, la vie en ville resterait supportable ; si elles n''agissent pas, en revanche, elle risque de devenir invivable d''ici quelques décennies, en particulier pour les personnes âgées et les jeunes enfants."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
